INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','possessive-s','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"possessive-s","title":"Possessive ’s","level":"A1","order":7,"summary":"Show ownership with singular nouns, regular plurals and irregular plurals.","learningGoals":["One owner","Plural owners","Read the whole phrase"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"One owner","explanation":"Add apostrophe plus s to a singular owner noun in the forms practised here. The owner comes before the thing owned.","examples":["the explorer’s compass","the rabbit’s hutch"]},{"title":"Plural owners","explanation":"For a regular plural already ending in s, add only an apostrophe. For an irregular plural without final s, add apostrophe plus s.","examples":["the explorers’ compasses","the children’s drawings"]},{"title":"Read the whole phrase","explanation":"The owner phrase determines apostrophe placement. The owned object can itself be singular or plural. Names ending in s have additional conventions outside this bank.","examples":["one student’s notebooks","several students’ classroom"]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-possessive-s"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"c51f43cc-ee2b-5461-aa7d-b0ce9ca925f2","topicSlug":"possessive-s","level":"A1","prompt":"The owner is one baker. Show owner